__NUXT_JSONP__("/th/how-to-apply/student-visa-f1", {data:[{details:{slug:"th",pageTitle:"วีซ่านักเรียน F1 | Mentor Language Institute",pageDescription:"กรุณาเลือกข้อมูลของคุณจากตัวเลือกด้านล่าง. หากคุณไม่แน่ใจเกี่ยวกับสถานการณ์ของคุณ คลิก \"อ่านต่อ\" สำหรับรายละเอียดเพิ่มเติม.",title:"วีซ่านักเรียน F1",image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fvisa_application.jpg",subtitle:["กรุณาเลือกข้อมูลของคุณจากตัวเลือกด้านล่าง. \u003Cbr \u002F\u003E หากคุณไม่แน่ใจเกี่ยวกับสถานการณ์ของคุณ คลิก \"อ่านต่อ\" สำหรับรายละเอียดเพิ่มเติม."],category:[{btn_visa:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Foverseas_btn_th.png",link:"\u002Fth\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Foverseas-students"},btn_transfer:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Ftransfer_student_btn_th.png",link:"\u002Fth\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Ftransfer-students"},btn_status:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fchange_status_btn_th.png",link:"\u002Fth\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fchange-of-status"}}],content:{subtitle:"มีคำถาม",description:["โดยปกติคุณจะต้องมีวีซ่านักเรียน เพื่อการเรียนระยะยาวในประเทศสหรัฐอเมริกา\u003Cbr \u002F\u003Eหากคุณไม่ทราบว่าคุณต้องการวีซ่าหรือไม่โปรดติดต่อเรา","เรามีให้บริการถึง 8 ภาษา"],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fcontact-us-th.jpg",link:"\u002Fth\u002Fcontact"}},dir:"\u002Fstudent-visa-f1",path:"\u002Fstudent-visa-f1\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:31.150Z",updatedAt:"2025-05-26T12:06:27.926Z"}}],fetch:{},mutations:void 0});